//! Single-Surface display selection, from farwing a87b8e7 stream_control/{tracks,wire}.
use serde_json::{json,Value};
use crate::protocol::{decode_wire,WireValue};
use std::time::{Duration,Instant};
pub fn direct_switch_enabled(multi_video:bool)->bool{cfg!(feature="direct-screen-setting")&&!multi_video}
fn fields(d:&[u8])->Result<Vec<crate::protocol::WireField<'_>>,&'static str>{if d.len()>65536{return Err("screen_message_limit")}decode_wire(d).map_err(|_|"screen_invalid_wire")}
fn num(d:&[u8],n:u32)->Option<u64>{fields(d).ok()?.into_iter().find_map(|f|match f.value{WireValue::Varint(v)if f.number==n=>Some(v),_=>None})}
fn blob(d:&[u8],n:u32)->Option<&[u8]>{fields(d).ok()?.into_iter().find_map(|f|match f.value{WireValue::Bytes(v)if f.number==n=>Some(v),_=>None})}
fn rect(d:&[u8])->Option<Value>{let lw=num(d,3).or_else(||num(d,5))?;let lh=num(d,4).or_else(||num(d,6))?;let w=num(d,5).filter(|v|*v>0).unwrap_or(lw);let h=num(d,6).filter(|v|*v>0).unwrap_or(lh);if [lw,lh,w,h].iter().any(|v|*v==0||*v>32768){return None}Some(json!({"width":w,"height":h,"logicalWidth":lw,"logicalHeight":lh,"left":num(d,1).unwrap_or(0)as i64,"top":num(d,2).unwrap_or(0)as i64}))}
struct Change{scale_seq:Option<u64>,registration_seq:Option<u64>,registration_ack:Option<bool>,id:u64,kind:&'static str,generation:u64,capture_generation:u64,sent:bool,reported:bool,frame:bool,matched:bool,target:Option<(u64,u64)>,began:Instant,error:Option<&'static str>}
#[derive(Default)]pub struct AdvancedControls{screens:Vec<Value>,current:Option<u64>,capture:Option<u64>,inventory_received:bool,generation:u64,capture_generation:u64,rejected:u64,epoch:u64,sequence:u64,change:Option<Change>,report_error:Option<Value>,capture_config_response:Option<Value>,message_fields:std::collections::BTreeMap<u32,u64>}
impl AdvancedControls{
 pub fn observe(&mut self,d:&[u8]){if let Ok(fields)=fields(d){for f in fields{if (3..=28).contains(&f.number){*self.message_fields.entry(f.number).or_default()+=1;}}}if self.parse(d).is_err(){self.rejected+=1;}self.reconcile_report();}
 fn parse(&mut self,d:&[u8])->Result<(),&'static str>{for f in fields(d)?{let WireValue::Bytes(p)=f.value else{continue};match f.number{
  7=>{let mut screens=vec![];let mut ids=std::collections::BTreeSet::new();for f in fields(p)?{if let(1,WireValue::Bytes(s))=(f.number,f.value){if screens.len()>=32{return Err("screen_inventory_limit")};let id=num(s,1).unwrap_or(0);if id>i32::MAX as u64||!ids.insert(id){return Err("screen_id_invalid_or_duplicate")};let name=blob(s,10).map(std::str::from_utf8).transpose().map_err(|_|"screen_name_utf8")?.unwrap_or("");if name.len()>512||name.chars().any(char::is_control){return Err("screen_name_limit")};
   // init_resolution is the connection snapshot, not the first advertised mode.
   let initial=self.screens.iter().find(|s|s["id"]==id).and_then(|s|s.get("initial")).filter(|s|s.is_object()).cloned().or_else(||blob(s,6).and_then(rect));let current=blob(s,4).and_then(rect);let geometry=initial.clone().or_else(||current.clone()).ok_or("screen_geometry_missing")?;let track=num(s,12).unwrap_or(0)as i64;if !(-1..32).contains(&track){return Err("screen_track_invalid")};screens.push(json!({"id":id,"name":name,"primary":num(s,7).unwrap_or(0)==1,"native":geometry,"initial":initial,"currentResolution":current,"fps":num(s,2),"resolutionType":num(s,11).filter(|v|*v<=4),"profileDimensionsReported":blob(s,4).is_some_and(|r|[3,4,5,6].iter().all(|f|num(r,*f).is_some_and(|v|(1..=32768).contains(&v)))),"videoTrackIndex":track}));}}
   if screens.is_empty(){return Err("screen_inventory_empty")};let current=num(p,2).unwrap_or(0);if !ids.contains(&current){return Err("screen_current_not_in_inventory")};self.screens=screens;self.current=Some(current);self.inventory_received=true;self.generation+=1;if self.capture.is_some_and(|id|!ids.contains(&id)){self.capture=None;}
  },12=>{fields(p)?;self.report_error=Some(json!({"action":num(p,1),"errorCode":num(p,2).map(|v|v as u32 as i32),"typeValue":num(p,4).map(|v|v as u32 as i32)}));},19=>{fields(p)?;self.capture_config_response=Some(json!({"requestSeq":num(p,1).map(|v|v as i64),"configFlag":num(p,2).map(|v|v as i64),"errorCode":num(p,3).map(|v|v as u32 as i32)}));},8=>{fields(p)?;if num(p,1).unwrap_or(0)==0{let id=num(p,2).unwrap_or(0);if self.screens.iter().any(|s|s["id"]==id){self.capture=Some(id);self.capture_generation+=1;}}},22=>{if let Some(c)=self.change.as_mut(){if c.registration_seq.is_some()&&blob(p,1).and_then(|h|num(h,1))==c.registration_seq{if let Some(r)=blob(p,11){fields(r)?;c.registration_ack=Some(num(r,1).unwrap_or(0)==0);}}}},_=>{}
 }}Ok(())}
 fn reconcile_report(&mut self){let Some(c)=self.change.as_mut()else{return};if !c.sent{return;}let Some(s)=self.screens.iter().find(|s|s["id"]==c.id)else{c.reported=false;c.error=Some("screen_removed");return};if c.kind!="switch"{return;}if c.registration_ack==Some(false){c.reported=false;c.error=Some("video_track_registration_rejected");return;}let fresh_capture=self.capture_generation>c.capture_generation&&self.capture==Some(c.id);let unique=self.screens.iter().filter(|s|s["videoTrackIndex"]==0).count()==1;let fresh_mapping=self.generation>c.generation&&(self.current==Some(c.id)||unique);if s["videoTrackIndex"]==0&&(fresh_capture||fresh_mapping){c.reported=true;}else if(fresh_capture||fresh_mapping)&&s["videoTrackIndex"].as_i64().is_some_and(|i|i>0){c.error=Some("screen_track_not_negotiated");}}
 pub fn active_id(&self)->Option<u64>{if let Some(c)=&self.change{return if c.kind=="switch"{c.reported.then_some(c.id)}else{Some(c.id)}}self.capture.or(self.current)}
 pub fn resolution_target(&self,native:bool)->Result<(u64,Value),&'static str>{let id=self.active_id().ok_or("screen_report_required")?;let s=self.screens.iter().find(|s|s["id"]==id).ok_or("screen_removed")?;let size=s.get(if native{"initial"}else{"currentResolution"}).filter(|s|s.is_object()).ok_or(if native{"screen_initial_size_unknown"}else{"screen_current_size_unknown"})?;Ok((id,size.clone()))}
 pub fn epoch(&self)->u64{self.epoch}
 // A verified replacement reader keeps the selected screen and request state,
 // but no prior frame may authorize input for the replacement stream.
 pub fn transport_restart(&mut self)->u64{if self.change.is_none(){if let Some(id)=self.capture.or(self.current){self.begin(id,"transport",None);if let Some(c)=self.change.as_mut(){c.sent=true;}return self.epoch}}self.epoch+=1;if let Some(c)=self.change.as_mut(){c.frame=false;c.matched=false;}self.epoch}
 // Restore only a host-reported pre-connection/current physical-mode mismatch.
 pub fn initial_restorations(&self)->Option<Vec<(u64,Value)>>{
  if !self.inventory_received||self.screens.iter().any(|s|!s["initial"].is_object()||!s["currentResolution"].is_object()){return None;}Some(self.screens.iter().filter_map(|s|{let initial=s.get("initial").filter(|v|v.is_object())?;let current=s.get("currentResolution").filter(|v|v.is_object())?;["width","height","logicalWidth","logicalHeight"].iter().any(|k|initial[*k]!=current[*k]).then(||(s["id"].as_u64().unwrap(),initial.clone()))}).collect())
 }
 pub fn begin_initial_restoration(&mut self,id:u64){self.begin(id,"preserve",None);}

 pub fn accepts_media(&self)->bool{self.change.as_ref().is_none_or(|c|c.kind!="switch"||(c.sent&&c.reported))}
 pub fn input_blocked(&self)->bool{self.change.as_ref().is_some_and(|c|!c.sent||!c.reported||!c.frame)}
 fn begin(&mut self,id:u64,kind:&'static str,target:Option<(u64,u64)>){self.epoch+=1;self.change=Some(Change{scale_seq:None,registration_seq:None,registration_ack:None,id,kind,generation:self.generation,capture_generation:self.capture_generation,sent:false,reported:kind!="switch",frame:false,matched:false,target,began:Instant::now(),error:None});}
 pub fn begin_resolution(&mut self,id:u64,w:u64,h:u64){self.begin(id,"resolution",Some((w,h)));}
 pub fn begin_stream_scale(&mut self,id:u64,w:u64,h:u64){self.begin(id,"stream_scale",Some((w,h)));}
 pub fn stream_scale_source(&self)->Option<(u32,u32)>{let id=self.active_id()?;let s=self.screens.iter().find(|s|s["id"]==id)?;let size=s.get("currentResolution").filter(|v|v.is_object()).or_else(||s.get("initial").filter(|v|v.is_object()))?;Some((u32::try_from(size["width"].as_u64()?).ok()?,u32::try_from(size["height"].as_u64()?).ok()?))}
 pub fn set_stream_scale_seq(&mut self,seq:u64){if let Some(c)=self.change.as_mut(){c.scale_seq=Some(seq)}}
 pub fn stream_scale_seq(&self)->Option<u64>{self.change.as_ref().and_then(|c|c.scale_seq)}
 pub fn is_stream_scale(&self)->bool{self.change.as_ref().is_some_and(|c|c.kind=="stream_scale")}
 pub fn prepare_switch(&mut self,v:&Value)->Result<(u64,Vec<u8>),&'static str>{if v["confirmed"]!=true{return Err("explicit_screen_selection_required")};let id=v["id"].as_u64().filter(|id|*id<=i32::MAX as u64).ok_or("invalid_screen_id")?;if !self.screens.iter().any(|s|s["id"]==id){return Err("screen_not_in_inventory")};self.begin(id,"switch",None);self.sequence+=1;let seq=4_000_000+self.sequence;if let Some(c)=self.change.as_mut(){c.registration_seq=Some(seq+100_000);}let mut action=vec![];crate::wire::int(1,8,&mut action);crate::wire::bytes(2,json!({"screen_id":id}).to_string().as_bytes(),&mut action);Ok((seq,crate::wire::envelope(seq,3,&action)))}
 pub fn direct_switch_no_registration(&mut self){if let Some(c)=self.change.as_mut(){c.registration_seq=None;c.registration_ack=None;}}
 pub fn mark_sent(&mut self,sent:bool){if let Some(c)=&mut self.change{c.sent=sent;if !sent{c.error=Some("display_send_incomplete");}}self.reconcile_report();}
 pub fn target_size(&self)->Option<(u64,u64)>{self.change.as_ref().and_then(|c|c.target)}
 pub fn observe_frame(&mut self,new_frame:bool,size_matches:bool){if let Some(c)=&mut self.change{if c.sent&&c.reported&&new_frame{c.frame=true;c.matched=size_matches;if c.kind=="switch"||c.kind=="stream_scale"||size_matches{c.error=None;}}let pending=!c.frame||(c.kind!="stream_scale"&&!c.matched);if c.began.elapsed()>=Duration::from_secs(12)&&pending&&c.error.is_none(){c.error=Some(if c.kind=="switch"||c.kind=="stream_scale"{"screen_switch_report_or_frame_timeout"}else{"resolution_not_observed"});}}}
 pub fn snapshot(&self)->Value{let c=self.change.as_ref();json!({"screens":self.screens,"inventoryReceived":self.inventory_received,"inventoryGeneration":self.generation,"currentReported":self.current,"captureReported":self.capture,"selectedScreen":self.active_id(),"switchCommandSupported":self.inventory_received,"switchCommandSent":c.is_some_and(|c|c.kind=="switch"&&c.sent),"requestedScreen":c.map(|c|c.id),"changeKind":c.map(|c|c.kind),"displayEpoch":self.epoch,"remoteSwitchConfirmed":c.filter(|c|c.kind=="switch").map(|c|c.reported),"videoFrameObserved":c.is_some_and(|c|c.frame),"resolutionMatched":c.is_some_and(|c|c.matched),"streamFrameCompatible":c.is_some_and(|c|c.kind=="stream_scale"&&c.frame),"displayPending":c.is_some_and(|c|(!c.frame||(c.kind!="stream_scale"&&!c.matched))&&c.error.is_none()),"inputBlocked":self.input_blocked(),"displayError":c.and_then(|c|c.error),"trackRegistrationAck":c.and_then(|c|c.registration_ack),"screenBlocker":"","touchMappingVerified":false,"privacy":{"supported":false,"requested":null,"reportedMode":null,"actualState":null,"error":null,"blocker":"Windows privacy controls remain unverified and disabled."},"reportError":self.report_error,"captureConfigResponse":self.capture_config_response,"messageFieldCounts":self.message_fields,"rejectedMessages":self.rejected})}
 pub fn command(&self,v:&Value)->Value{match v["action"].as_str(){Some("status")=>self.snapshot(),Some("privacy")=>json!({"error":"windows_privacy_protocol_unverified","sent":false,"remoteAck":null}),_=>json!({"error":"invalid_advanced_control_action","sent":false})}}
}
#[cfg(test)]mod tests{
 use super::*;fn screen(id:u64,w:u64,h:u64,t:i64)->Vec<u8>{let mut s=vec![];crate::wire::int(1,id,&mut s);let mut r=vec![];for(f,v)in[(3,w),(4,h),(5,w),(6,h)]{crate::wire::int(f,v,&mut r)}crate::wire::bytes(6,&r,&mut s);crate::wire::bytes(4,&r,&mut s);crate::wire::int(12,t as u64,&mut s);s}
 fn inv(a:&mut AdvancedControls,id:u64,rows:&[(u64,u64,u64,i64)]){let mut p=vec![];for&(id,w,h,t)in rows{crate::wire::bytes(1,&screen(id,w,h,t),&mut p)}crate::wire::int(2,id,&mut p);a.observe(&crate::wire::envelope(1,7,&p));}
 #[test]fn initial_display_guard_uses_only_original_physical_rectangles(){let mut a=AdvancedControls::default();assert!(a.initial_restorations().is_none());inv(&mut a,0,&[(0,2560,1600,0),(7,1920,1080,-1)]);assert!(a.initial_restorations().unwrap().is_empty());a.screens[1]["currentResolution"]["width"]=json!(1280);a.screens[1]["currentResolution"]["height"]=json!(720);let plans=a.initial_restorations().unwrap();assert_eq!(plans.len(),1);assert_eq!(plans[0].0,7);assert_eq!(plans[0].1["width"],1920);a.begin_initial_restoration(0);a.mark_sent(true);assert!(a.input_blocked());a.observe_frame(true,true);assert!(!a.input_blocked());a.screens[0]["initial"]=Value::Null;assert!(a.initial_restorations().is_none());}
 #[test]fn display_native_portrait_stable_ids(){let mut a=AdvancedControls::default();inv(&mut a,0,&[(0,2560,1600,0),(7,1600,2560,-1)]);assert_eq!(a.resolution_target(true).unwrap().1["width"],2560);let(_,p)=a.prepare_switch(&json!({"id":7,"confirmed":true})).unwrap();assert_eq!(num(blob(&p,3).unwrap(),1),Some(8));assert_eq!(serde_json::from_slice::<Value>(blob(blob(&p,3).unwrap(),2).unwrap()).unwrap()["screen_id"],7);a.mark_sent(true);assert!(!a.accepts_media());a.observe_frame(true,true);assert!(a.input_blocked());inv(&mut a,7,&[(7,1600,2560,0),(0,2560,1600,-1)]);assert!(a.accepts_media());assert!(a.input_blocked());a.observe_frame(true,true);assert!(!a.input_blocked());assert_eq!(a.resolution_target(true).unwrap().1["height"],2560);}
 #[test]fn replacement_transport_requires_new_epoch_frame_without_changing_screen(){let mut a=AdvancedControls::default();inv(&mut a,7,&[(7,1600,2560,0)]);let first=a.epoch();assert_eq!(a.active_id(),Some(7));let next=a.transport_restart();assert!(next>first);assert_eq!(a.active_id(),Some(7));assert!(a.input_blocked());a.observe_frame(true,true);assert!(!a.input_blocked());}
 #[test]fn display_unknown_and_stale_reports(){let mut a=AdvancedControls::default();inv(&mut a,0,&[(0,2560,1440,0),(4,1600,2560,-1)]);assert!(a.prepare_switch(&json!({"id":1,"confirmed":true})).is_err());a.prepare_switch(&json!({"id":4,"confirmed":true})).unwrap();a.mark_sent(true);inv(&mut a,0,&[(0,2560,1440,0),(4,1600,2560,-1)]);assert!(!a.accepts_media());a.change.as_mut().unwrap().began=Instant::now()-Duration::from_secs(13);a.observe_frame(false,false);assert!(a.snapshot()["displayError"].is_string());}
 #[test]fn display_initial_and_malformed_inventory(){let mut a=AdvancedControls::default();inv(&mut a,0,&[(0,2560,1600,0)]);inv(&mut a,0,&[(0,1280,800,0)]);assert_eq!(a.resolution_target(true).unwrap().1["width"],2560);inv(&mut a,0,&[(0,1920,1080,0),(0,1920,1080,0)]);assert_eq!(a.snapshot()["screens"].as_array().unwrap().len(),1);assert_eq!(a.snapshot()["rejectedMessages"],1);assert_eq!(a.command(&json!({"action":"privacy"}))["sent"],false);}
 #[test]fn display_requested_size_is_not_output(){let mut a=AdvancedControls::default();inv(&mut a,0,&[(0,2560,1600,0)]);a.begin_resolution(0,2560,1600);a.mark_sent(true);assert!(a.input_blocked());a.observe_frame(true,false);assert!(!a.input_blocked());assert_eq!(a.snapshot()["resolutionMatched"],false);}
 #[test]fn resolution_type_is_per_reported_screen_and_unknown_is_null(){
  let mut a=AdvancedControls::default();let mut first=screen(7,1600,2560,0);crate::wire::int(11,3,&mut first);
  let mut invalid=screen(9,1920,1080,-1);crate::wire::int(11,9,&mut invalid);
  let missing=screen(11,1280,720,-1);let mut p=vec![];
  for s in [&first,&invalid,&missing]{crate::wire::bytes(1,s,&mut p)}crate::wire::int(2,7,&mut p);
  a.observe(&crate::wire::envelope(1,7,&p));let rows=a.snapshot()["screens"].as_array().unwrap().clone();
  assert_eq!(rows[0]["resolutionType"],3);assert!(rows[1]["resolutionType"].is_null());assert!(rows[2]["resolutionType"].is_null());
  assert_eq!(rows[0]["currentResolution"]["width"],1600);assert_eq!(rows[0]["currentResolution"]["height"],2560);
  assert_eq!(rows[0]["currentResolution"]["logicalWidth"],1600);assert_eq!(rows[0]["currentResolution"]["logicalHeight"],2560);
 }
 #[test]fn profile_requires_all_four_actual_wire_dimensions(){
  let mut a=AdvancedControls::default();let mut s=vec![];crate::wire::int(1,7,&mut s);
  let mut r=vec![];crate::wire::int(5,1600,&mut r);crate::wire::int(6,2560,&mut r);
  crate::wire::bytes(4,&r,&mut s);crate::wire::bytes(6,&r,&mut s);crate::wire::int(11,3,&mut s);crate::wire::int(12,0,&mut s);
  let mut p=vec![];crate::wire::bytes(1,&s,&mut p);crate::wire::int(2,7,&mut p);a.observe(&crate::wire::envelope(1,7,&p));
  let status=a.snapshot();assert_eq!(status["screens"][0]["currentResolution"]["logicalWidth"],1600);
  assert_eq!(status["screens"][0]["profileDimensionsReported"],false);
 }
 #[test]fn direct_switch_is_opt_in_and_never_changes_multi(){assert_eq!(direct_switch_enabled(false),cfg!(feature="direct-screen-setting"));assert!(!direct_switch_enabled(true));}
 #[test]fn direct_switch_needs_fresh_mapping_and_frame(){let mut a=AdvancedControls::default();inv(&mut a,0,&[(0,1920,1080,0),(7,1600,2560,-1)]);a.prepare_switch(&json!({"id":7,"confirmed":true})).unwrap();a.direct_switch_no_registration();a.mark_sent(true);a.observe_frame(true,true);assert!(a.input_blocked());inv(&mut a,7,&[(0,1920,1080,-1),(7,1600,2560,0)]);assert!(a.input_blocked());a.observe_frame(false,false);assert!(a.input_blocked());a.observe_frame(true,true);assert!(!a.input_blocked());assert!(a.snapshot()["trackRegistrationAck"].is_null());}
 #[test]fn stream_compatible_frame_does_not_claim_exact_size(){let mut a=AdvancedControls::default();inv(&mut a,7,&[(7,1600,2560,0)]);a.begin_stream_scale(7,800,1280);a.mark_sent(true);assert!(a.input_blocked());a.observe_frame(true,false);let status=a.snapshot();assert_eq!(status["streamFrameCompatible"],true);assert_eq!(status["resolutionMatched"],false);assert_eq!(status["displayPending"],false);assert_eq!(status["inputBlocked"],false);}
 #[test]fn display_registration_rejection_and_removed_target_block_input(){let mut a=AdvancedControls::default();inv(&mut a,0,&[(0,2560,1600,0),(7,1600,2560,-1)]);let(seq,_)=a.prepare_switch(&json!({"id":7,"confirmed":true})).unwrap();a.mark_sent(true);let mut h=vec![];crate::wire::int(1,seq+100_000,&mut h);let mut error=vec![];crate::wire::int(1,1,&mut error);let mut rpc=vec![];crate::wire::bytes(1,&h,&mut rpc);crate::wire::bytes(11,&error,&mut rpc);a.observe(&crate::wire::envelope(0,22,&rpc));inv(&mut a,7,&[(0,2560,1600,-1),(7,1600,2560,0)]);a.observe_frame(true,true);assert!(a.input_blocked());assert_eq!(a.snapshot()["displayError"],"video_track_registration_rejected");a.begin_resolution(7,1600,2560);a.mark_sent(true);assert_eq!(a.resolution_target(true).unwrap().0,7);inv(&mut a,0,&[(0,2560,1600,0)]);assert!(a.input_blocked());assert_eq!(a.snapshot()["displayError"],"screen_removed");}
 #[test]fn numeric_reports_are_bounded_and_do_not_record_messages(){let mut a=AdvancedControls::default();let mut report=vec![];crate::wire::int(1,2,&mut report);crate::wire::int(2,(-7i64)as u64,&mut report);crate::wire::int(4,3,&mut report);crate::wire::bytes(3,b"private",&mut report);a.observe(&crate::wire::envelope(0,12,&report));let mut response=vec![];crate::wire::int(1,55,&mut response);crate::wire::int(2,6,&mut response);crate::wire::int(3,(-2i64)as u64,&mut response);a.observe(&crate::wire::envelope(0,19,&response));let status=a.snapshot();assert_eq!(status["reportError"]["errorCode"],-7);assert_eq!(status["captureConfigResponse"]["requestSeq"],55);assert_eq!(status["captureConfigResponse"]["errorCode"],-2);assert!(!status.to_string().contains("private"));}
}
